const inicio = Date.now();
const fonte = $json.fonte;
const janela = $json.janela;
const modo = $json.modo;
const versaoApi = 'v1beta';

const propertyId = String(fonte.externalId).replace(/\D/g, '');
const limite = modo === 'amostra' ? 500 : 100000;

const body = {
  dateRanges: [{ startDate: janela.start, endDate: janela.end }],
  dimensions: [{ name: 'date' }, { name: 'sessionDefaultChannelGroup' }],
  metrics: [{ name: 'sessions' }, { name: 'totalUsers' }, { name: 'newUsers' }, { name: 'keyEvents' }, { name: 'totalRevenue' }],
  limit: limite,
};

function devolver(linhas, falhas, requests, bytes) {
  return [{
    json: {
      linhas,
      volumetria: { linhas: linhas.length, bytes, requests, duracaoMs: Date.now() - inicio },
      falhas,
      requests,
      versaoApi,
    },
  }];
}

let resposta;
try {
  resposta = await this.helpers.httpRequestWithAuthentication.call(this, 'googleOAuth2Api', {
    method: 'POST',
    url: `https://analyticsdata.googleapis.com/${versaoApi}/properties/${propertyId}:runReport`,
    headers: { 'Content-Type': 'application/json' },
    body,
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
} catch (erro) {
  return devolver([], [{ causa: 'api_recusou', detalhe: `falha de rede: ${erro.message}` }], 1, 0);
}

if (resposta.statusCode === 401 || resposta.statusCode === 403) {
  const detalhe = resposta.body?.error?.message || `HTTP ${resposta.statusCode}`;
  return devolver([], [{ causa: 'reauth_pending', detalhe }], 1, 0);
}

if (resposta.statusCode < 200 || resposta.statusCode >= 300) {
  const detalhe = resposta.body?.error?.message || `HTTP ${resposta.statusCode}`;
  return devolver([], [{ causa: 'api_recusou', detalhe }], 1, 0);
}

const linhasBrutas = resposta.body?.rows ?? [];
const bytes = JSON.stringify(resposta.body).length;

function formatarData(bruta) {
  const s = String(bruta ?? '');
  return s.length === 8 ? `${s.slice(0, 4)}-${s.slice(4, 6)}-${s.slice(6, 8)}` : null;
}

const linhas = linhasBrutas.map((linha) => {
  const dim = linha.dimensionValues ?? [];
  const met = linha.metricValues ?? [];
  return {
    metricDate: formatarData(dim[0]?.value),
    canal: dim[1]?.value ?? null,
    sessoes: Number(met[0]?.value ?? 0),
    usuarios: Number(met[1]?.value ?? 0),
    novosUsuarios: Number(met[2]?.value ?? 0),
    conversoes: Number(met[3]?.value ?? 0),
    receita: Number(met[4]?.value ?? 0),
  };
});

if (linhas.length === 0) {
  return devolver([], [{ causa: 'sem_dados_no_periodo', detalhe: null }], 1, bytes);
}

return devolver(linhas, [], 1, bytes);
